import Image, { StaticImageData } from 'next/image';

import Button from './Button';

interface AsideButtonPropsType {
    image: StaticImageData;
    pageName: string;
    innerRef?: (node: any) => void;
    onClick?: () => void;
}


export default function AsideButton({ image, pageName, innerRef, onClick }: AsideButtonPropsType) {
    return (
        <Button innerRef={innerRef} onClick={onClick} className='z-10 flex-col w-full !gap-1 !pb-2 !shadow-none !text-black' name={pageName}>
            <Image
                width={25} height={25}
                src={image} alt={`ícone da página ${pageName}`}
            />
        </Button>
    );
}

import { useEffect, useState } from 'react';
import useSelectedClasses from '@/app/hooks/useSelectedClasses';
import useShowPopUpContent from '@/app/hooks/useShowPopUpContent';

import { ClassType, DisciplineType } from '@/app/utils/api/searchDiscipline';
import { ClassValueType } from '@/app/contexts/SelectedClassesContext/types';

import DisciplineOptionForm from './Form/DisciplineOptionForm';
import DisciplineFragment from './DisciplineFragment';

import { AsideSchedulePopUpJSXPropsType, AsideSchedulePopUpPropsType, CheckDisciplineObjPropsType } from './types/types';

import _ from 'lodash';

function checkDisciplineObj(props: CheckDisciplineObjPropsType) {
    const { disciplineObj, newSelectedClasses, classId, disciplineId, newClassInfo } = props;

    if (disciplineObj.has(classId)) {
        disciplineObj.delete(classId);

        if (!disciplineObj.size) newSelectedClasses.delete(disciplineId);
    } else disciplineObj.set(classId, newClassInfo);
}

function createNewClassInfo(props: { cls: ClassType, discipline: DisciplineType }) {
    const { cls, discipline } = props;

    return {
        class: cls,
        discipline: {
            id: discipline.id,
            name: discipline.name,
            code: discipline.code
        }
    };
}

function AsideSchedulePopUpJSX(props: AsideSchedulePopUpJSXPropsType) {
    const { showPopUpContent, searchedDisciplineInfos, setSearchedDisciplineInfos, handleSelectClass } = props;

    return (
        <div className='flex justify-center'>
            <div
                ref={props.divAddClassRef}
                className={`fixed flex flex-col justify-between items-center w-11/12 ${showPopUpContent ? 'py-5 h-5/6' : 'h-0'} transition-all duration-500 bottom-0 rounded-t-[40px] bg-snow-secondary z-10`}
            >
                {showPopUpContent &&
                    <section className='flex flex-col items-center gap-5 w-full h-full text-[#333333]'>
                        <DisciplineOptionForm setInfos={setSearchedDisciplineInfos} />
                        <div className='flex flex-col gap-2 w-10/12 overflow-auto h-full'>
                            {searchedDisciplineInfos.map((discipline, index) =>
                                <DisciplineFragment key={index} index={index}
                                    discipline={discipline} disciplineInfos={{ searchedDisciplineInfos, setSearchedDisciplineInfos }}
                                    handleSelectClass={handleSelectClass}
                                />
                            )}
                        </div>
                    </section>
                }
            </div>
        </div >
    );
}

export default function AsideSchedulePopUp(props: AsideSchedulePopUpPropsType) {
    const { showPopUpContent } = useShowPopUpContent();
    const { selectedClasses, setSelectedClasses } = useSelectedClasses();
    const [searchedDisciplineInfos, setSearchedDisciplineInfos] = useState<Array<DisciplineType>>([]);

    useEffect(() => {
        if (!showPopUpContent) setSearchedDisciplineInfos([]);
    }, [showPopUpContent, setSearchedDisciplineInfos]);

    function handleSelectClass(discipline: DisciplineType, cls: ClassType) {
        const disciplineId = discipline.id;
        const classId = cls.id;

        const newSelectedClasses = _.cloneDeep(selectedClasses);
        const disciplineObj = newSelectedClasses.get(disciplineId);

        const newClassInfo = createNewClassInfo({ cls, discipline });

        if (disciplineObj) checkDisciplineObj({ disciplineObj, newSelectedClasses, classId, disciplineId, newClassInfo });
        else {
            const newDiscipline = new Map<number, ClassValueType>();
            newDiscipline.set(classId, newClassInfo);

            newSelectedClasses.set(disciplineId, newDiscipline);
        }

        setSelectedClasses(newSelectedClasses);
    }

    return AsideSchedulePopUpJSX({
        divAddClassRef: props.divAddClassRef,
        showPopUpContent, searchedDisciplineInfos, setSearchedDisciplineInfos,
        handleSelectClass
    });
}

import { ClassType, DisciplineType } from '@/app/utils/api/searchDiscipline';
import { HTMLProps, MouseEventHandler, useEffect, useState } from 'react';

import useSelectedClasses from '@/app/hooks/useSelectedClasses';
import ClassInfo from '../ClassInfo';
import Image from 'next/image';

import addIcon from '@/public/icons/add.jpg';
import removeIcon from '@/public/icons/remove.jpg';

interface ClassInfoBoxPropsType extends HTMLProps<HTMLDivElement> {
    currentDiscipline: DisciplineType,
    currentClass: ClassType,
}

export default function ClassInfoBox({ currentDiscipline, currentClass, ...props }: ClassInfoBoxPropsType) {
    const { classesChange, selectedClasses } = useSelectedClasses();
    const [selected, setSelected] = useState(false);

    useEffect(() => {
        if (selectedClasses.get(currentDiscipline.id)?.has(currentClass.id)) setSelected(true);
        else setSelected(false);
    }, [selectedClasses, classesChange, currentDiscipline, currentClass]);

    return (
        <div
            className={`grid grid-cols-7 ${selected ? 'bg-primary bg-opacity-40' : 'hover:bg-gray-300'} hover:bg-opacity-40 hover:cursor-pointer rounded-md py-1 px-2 ${props.className || ''}`}
        >
            <ClassInfo currentClass={{
                class: currentClass,
                discipline: {
                    id: currentDiscipline.id,
                    name: currentDiscipline.name,
                    code: currentDiscipline.code
                }
            }} />
            <button
                onClick={props.onClick as MouseEventHandler<HTMLButtonElement> | undefined}
                className='hover:cursor-pointer col-start-7 flex justify-center items-center'>
                {selected ?
                    <Image
                        width={25} height={25}
                        src={removeIcon} alt='ícone remover matéria'
                    />
                    : <Image
                        width={25} height={25}
                        src={addIcon} alt='ícone adicionar matéria'
                    />
                }
            </button>
        </div>
    );
}

import { Fragment } from 'react';
import Image from 'next/image';
import ClassInfoBox from './ClassInfoBox';

import { ClassType, DisciplineType } from '@/app/utils/api/searchDiscipline';

import expand_more from '@/public/icons/expand_more.png';
import expand_less from '@/public/icons/expand_less.png';

interface DisciplineFragmentPropsType {
    index: number,
    discipline: DisciplineType,
    disciplineInfos: {
        searchedDisciplineInfos: Array<DisciplineType>,
        setSearchedDisciplineInfos: React.Dispatch<React.SetStateAction<DisciplineType[]>>
    }
    handleSelectClass: (discipline: DisciplineType, cls: ClassType) => void
}

function DisciplineFragmentJSX({ handleDisciplineToggle, ...props }: {
    handleDisciplineToggle: (index: number) => void,
    props: DisciplineFragmentPropsType
}) {
    const { index, discipline, handleSelectClass } = props.props;

    return (
        <Fragment>
            <button
                onClick={() => handleDisciplineToggle(index)}
                className='flex items-center gap-3 relative'
            >
                <Image
                    className='absolute left-0'
                    height={24} width={24}
                    src={discipline.expanded ? expand_more : expand_less} alt="expand icon" />
                <span className='font-semibold text-left pl-6'>
                    {discipline.name} - {discipline.code}
                </span>
            </button>
            {discipline.expanded &&
                <div className='flex flex-col gap-2'>
                    {discipline.classes.map((cls, index) =>
                        <ClassInfoBox
                            key={index} currentClass={cls} currentDiscipline={discipline}
                            onClick={() => handleSelectClass(discipline, cls)}
                        />
                    )}
                </div>
            }
        </Fragment>
    );
}

export default function DisciplineFragment(props: DisciplineFragmentPropsType) {
    const { searchedDisciplineInfos, setSearchedDisciplineInfos } = props.disciplineInfos;

    function handleDisciplineToggle(index: number) {
        let newInfo: Array<DisciplineType> = [];
        searchedDisciplineInfos.forEach((discipline, number) => {
            if (number != index) newInfo.push({
                ...discipline,
                expanded: false
            });
            else newInfo.push({
                ...discipline,
                expanded: !discipline.expanded
            });
        });

        setSearchedDisciplineInfos(newInfo);
    }

    return DisciplineFragmentJSX({ handleDisciplineToggle, props });
}

import { ChangeEvent, Dispatch, SetStateAction, useEffect, useState } from 'react';
import useYearPeriod from '@/app/hooks/useYearPeriod';
import useSelectedClasses from '@/app/hooks/useSelectedClasses';

import { errorToast } from '@/app/utils/toast';

import { DisciplineOptionFormPropsType, FormType, defaultFormData } from '../types/types';
import { DisciplineType } from '@/app/utils/api/searchDiscipline';

import InputForm from './InputForm';

interface FormPropsType {
    form: FormType,
    disableDefault: boolean,
    setInfos: Dispatch<SetStateAction<Array<DisciplineType>>>,
    handleYearAndPeriodChange: (event: ChangeEvent<HTMLSelectElement>) => void,
}

function Form(props: FormPropsType) {
    const { formData, setFormData } = props.form;
    const { disableDefault, handleYearAndPeriodChange } = props;

    const { periods } = useYearPeriod();

    return (
        <>
            <div className='flex flex-col items-center gap-1 w-full max-w-md'>
                <span className='text-xl font-semibold'>Ano/Período</span>
                <select
                    className='bg-white shadow-md h-14 w-11/12 p-2 rounded-xl'
                    value={`${formData.year}/${formData.period}`}
                    onChange={event => handleYearAndPeriodChange(event)}
                >
                    <option disabled={disableDefault} value="">Selecione uma opção</option>
                    {periods['year/period'].map((item, index) => <option key={index} value={item}>{item}</option>)}
                </select>
            </div>
            <div className='flex flex-col items-center gap-1 w-full max-w-md'>
                <span className='text-xl font-semibold'>Matéria</span>
                <InputForm form={{ formData, setFormData }} setInfos={props.setInfos} />
            </div>
        </>
    );
}

function getYearAndPeriod(text: string) {
    const year = text.split('/')[0] || defaultFormData.year;
    const period = text.split('/')[1] || defaultFormData.period;

    return { year, period };
}

function handleChangeYearAndPeriod(text: string, currentYearPeriod: string, selectedClasses: any, handleSetYearPeriod: () => void) {
    if (currentYearPeriod && selectedClasses && currentYearPeriod != text) {
        errorToast('Há disciplinas selecionadas de outro período, não pode haver mistura!');
    } else handleSetYearPeriod();
}

export default function DisciplineOptionForm(props: DisciplineOptionFormPropsType) {
    const { selectedClasses, currentYearPeriod, setCurrentYearPeriod } = useSelectedClasses();
    const [disableDefault, setDisableDefault] = useState(false);
    const [formData, setFormData] = useState(defaultFormData);

    useEffect(() => {
        if (!disableDefault && formData == defaultFormData && selectedClasses.size) {
            const { year, period } = getYearAndPeriod(currentYearPeriod);
            setFormData({ ...formData, year: year, period: period });
            setDisableDefault(true);
        }
    }, [disableDefault, currentYearPeriod, formData, selectedClasses]);

    function handleYearAndPeriodChange(event: ChangeEvent<HTMLSelectElement>) {
        const text = event.target.value.trim();
        const { year, period } = getYearAndPeriod(text);

        if (year && period) {
            const handleSetYearPeriod = () => {
                setFormData({ ...formData, year: year, period: period });
                props.setInfos([]);
                setCurrentYearPeriod(text);
                setDisableDefault(true);
            };
            handleChangeYearAndPeriod(text, currentYearPeriod, selectedClasses.size, handleSetYearPeriod);
        }
    }

    return <Form form={{ formData, setFormData }} disableDefault={disableDefault}
        handleYearAndPeriodChange={handleYearAndPeriodChange} setInfos={props.setInfos} />;
}

import { useRef } from 'react';

import toast from 'react-hot-toast';

import Image from 'next/image';

import searchIcon from '@/public/icons/search.jpg';

import searchDiscipline, { DisciplineType } from '@/app/utils/api/searchDiscipline';

import { FormData, FormType, InputFormPropsType } from '../types/types';

interface FormPropsType {
    form: FormType,
    handleSearch: (event: React.FormEvent<HTMLFormElement>) => Promise<void>,
    inputRef: React.RefObject<HTMLInputElement>
}

function Form(props: FormPropsType) {
    const { formData, setFormData } = props.form;
    const { handleSearch, inputRef } = props;

    return (
        <form className='flex items-center w-11/12 px-2 bg-white shadow-md rounded-xl' onSubmit={handleSearch}>
            <input
                type="text"
                placeholder='Matéria ou Professor...'
                value={formData.search}
                onChange={(e) => setFormData({ ...formData, search: e.target.value })}
                ref={inputRef}
                className='h-14 p-2 w-full rounded-xl focus:outline-none'
            />
            <button type='submit' >
                <Image
                    width={30} height={30}
                    src={searchIcon} alt='ícone de pesquisa'
                />
            </button>
        </form>
    );
}

async function makeDisciplineSearch(textSearch: string, year: string, period: string, setInfos: (infos: Array<DisciplineType>) => void) {
    const data = await searchDiscipline(textSearch, year, period);
    if (data) {
        let infos: Array<DisciplineType> = [];
        data.forEach(discipline => infos.push({ ...discipline, expanded: false }));
        setInfos(infos);
    }
}

async function handleDisciplineSearch(formData: FormData, setInfos: (infos: Array<DisciplineType>) => void) {
    const { search, year, period } = formData;
    const textSearch = search.trim();

    if (!textSearch) toast.error('Escreva no nome da disciplina');
    else if (!year || !period) toast.error('Escolha o ano/período');
    else await makeDisciplineSearch(textSearch, year, period, setInfos);
}

export default function InputForm(props: InputFormPropsType) {
    const inputRef = useRef<HTMLInputElement>(null);
    const { formData } = props.form;

    async function handleSearch(event: React.FormEvent<HTMLFormElement>) {
        event.preventDefault();

        if (inputRef && inputRef.current) inputRef.current.blur();

        await handleDisciplineSearch(formData, props.setInfos);
    }

    return <Form form={props.form} handleSearch={handleSearch} inputRef={inputRef} />;
}

'use client';

import styles from '@/app/styles/tooltip.module.css';

import Image from 'next/image';

import useWindowDimensions from '../../hooks/useWindowDimensions';
import { useEffect, useState } from 'react';

import questionIcon from '@/public/icons/question.jpg';
import closeIcon from '@/public/icons/close.jpg';

interface TooltipPropsType {
    children: React.ReactNode,
};

export const isMobile = (width?: number) => {
    return width && width <= 768;
};

export default function Tooltip({ children }: TooltipPropsType) {
    const [active, setActive] = useState(false);
    const { width } = useWindowDimensions();

    useEffect(() => {
        function keyPress(event: KeyboardEvent) {
            if (event.key === 'Escape') setActive(false);
        }

        if (active) document.addEventListener('keydown', keyPress);

        return () => {
            document.removeEventListener('keydown', keyPress);
        };
    }, [active]);

    return (
        <div className={styles.tooltip}>
            <span
                onClick={() => setActive(true)}
                className='flex justify-center items-center text-xs border-black border-solid border-2 rounded-full h-5 w-5 hover:bg-gray-300'>
                <Image
                    width={15} height={15}
                    src={questionIcon} alt='ícone de interrogação'
                />
            </span>
            <span className={`${active ? 'visible' : 'invisible'} ${styles.inside} ${styles.tooltiptext} p-2`}>
                <div className='relative flex flex-col gap-1 justify-center items-center rounded-md p-5 bg-snow-primary'>
                    {children}
                    <button
                        onClick={() => setActive(false)}
                        className={`absolute right-2 ${isMobile(width) ? 'bottom-2' : 'top-2'}`}
                    >
                        <Image
                            src={closeIcon}
                            alt='fechar'
                        />
                    </button>
                </div>
            </span>
        </div>
    );
}

import { HTMLProps, LegacyRef } from 'react';

interface ButtonPropsType extends HTMLProps<HTMLButtonElement> {
    children: React.ReactNode;
    innerRef?: LegacyRef<HTMLButtonElement> | undefined
}

export default function Button({ children, innerRef, ...props }: ButtonPropsType) {
    return (
        <button
            ref={innerRef}
            {...props}
            className={`flex justify-center items-center gap-3 font-medium rounded-xl shadow py-3 px-5 hover:shadow-md transition-all duration-300 text-white ${props.className || ''}`}
            type='submit'
        >
            {children}
        </button>
    );
}

import { Fragment } from 'react';

import { ClassValueType } from '../contexts/SelectedClassesContext/types';

import Tooltip from './AsideSchedulePopUp/Tooltip';

interface ClassInfoPropsType {
    currentClass: ClassValueType
}

export function generateSpecialDates(special_dates: Array<Array<string>>, days: Array<string>) {
    return special_dates.map((specialDate, index) => {
        const day = specialDate[0];
        const start = parseInt(specialDate[1]) - 1;
        const end = parseInt(specialDate[2]) - 1;

        function make_days(start: number, end: number) {
            return days.slice(start, end + 1).map((day, index) =>
                <div className='pl-3' key={index}>
                    {day}
                </div>
            );
        }

        return (
            <Fragment key={index}>
                <span className='font-semibold'>
                    {day}
                </span>
                {make_days(start, end)}
            </Fragment>
        );
    });
}

export default function ClassInfo({ currentClass }: ClassInfoPropsType) {
    return (
        <div className = "col-span-6">
            <div>
                <span className='font-semibold'>Sala:</span> {currentClass.class.classroom}
            </div>
            <div className='flex gap-1'>
                <span className='font-semibold'>Horários:</span> {currentClass.class.schedule}
                <Tooltip>
                    <div className='flex flex-col gap-1 w-64'>
                        <span className='text-center font-semibold text-lg'>Horários</span>
                        {!currentClass.class.special_dates.length ?
                            currentClass.class.days.map((day, index) =>
                                <div key={index}>
                                    {day}
                                </div>
                            ) : generateSpecialDates(
                                currentClass.class.special_dates,
                                currentClass.class.days
                            )}
                    </div>
                </Tooltip>
            </div>
            <div>
                <span className='font-semibold'>Professor:</span> {currentClass.class.teachers[0]} {currentClass.class.teachers.length > 1 && 'e outros'}
            </div>
        </div>
    );
}

import Image from 'next/image';

import { ClassValueType } from '../contexts/SelectedClassesContext/types';

import useSelectedClasses from '../hooks/useSelectedClasses';

import ClassInfo from './ClassInfo';

import deleteIcon from '../../public/icons/delete.jpg';

import _ from 'lodash';

interface DisciplineBoxPropsType {
    currentClass: ClassValueType
    discipline: {
        id: number,
        name: string,
        code: string
    }
}

export default function DisciplineBox({ currentClass, discipline }: DisciplineBoxPropsType) {
    const { selectedClasses, setSelectedClasses } = useSelectedClasses();

    function handleDeleteClass() {
        const newSelectedClasses = _.cloneDeep(selectedClasses);
        newSelectedClasses.get(discipline.id)?.delete(currentClass.class.id);
        if (!newSelectedClasses.get(discipline.id)?.size) {
            newSelectedClasses.delete(discipline.id);
        }
        setSelectedClasses(newSelectedClasses);
    }

    return (
        <span className='relative flex justify-between rounded-lg w-10/12 py-2 pl-4 pr-8 shadow-lg bg-snow-primary'>
            <div>
                <section>
                    <span className='font-semibold'>Código: </span> {discipline.code}
                </section>
                <ClassInfo currentClass={currentClass} />
            </div>
            <button onClick={handleDeleteClass} className='absolute right-1 top-0 bottom-0 my-auto'>
                <Image height={24} width={24} src={deleteIcon} alt="deletar" />
            </button>
        </span>
    );
}

'use client';

import { useState } from 'react';
import useWindowDimensions from '../hooks/useWindowDimensions';
import useUser from '../hooks/useUser';

import { days, months } from '../utils/dates';

const currentDateObject = new Date(
    new Date().toLocaleString('en', {
