import React, { createContext, useEffect, useState } from 'react';

import { ClassType } from '../utils/api/searchDiscipline';

export interface ScheduleClassType extends ClassType {
    discipline: {
        id: number;
        name: string;
        code: string;
        department: number;
        unicode_name: string;
    }
};

export interface CloudScheduleType {
    id: number;
    created_at: string;
    classes: Array<ScheduleClassType>;
};

export interface ScheduleAPIType {
    schedules: Array<ScheduleClassType>;
    message: string;
};

type SchedulesType = Array<Array<ScheduleClassType>>;
type SchedulesCloudType = Array<CloudScheduleType>;

interface SchedulesContextType {
    localSchedules: SchedulesType;
    setLocalSchedules: (newSchedules: Array<ScheduleClassType> | Array<Array<ScheduleClassType>>, add?: boolean) => void;
    cloudSchedules: SchedulesCloudType;
    setCloudSchedules: (newSchedules: SchedulesCloudType) => void;
}

export const SchedulesContext = createContext<SchedulesContextType>({} as SchedulesContextType);

export default function SchedulesContextProvider({ children }: {
    children: React.ReactNode;
}) {
    const [localSchedules, setLocalDefaultSchedules] = useState<SchedulesType>([] as SchedulesType);
    const [cloudSchedules, setCloudDefaultSchedules] = useState<SchedulesCloudType>([] as SchedulesCloudType);

    useEffect(() => {
        const localJSON = JSON.parse(localStorage.getItem('schedules') || '[]');
        const localSchedulesFromJSON: SchedulesType = localJSON;
        setLocalDefaultSchedules(localSchedulesFromJSON);
    }, []);

    const setLocalSchedules = (newSchedules: Array<ScheduleClassType> | Array<Array<ScheduleClassType>>, add: boolean = true) => {
        if (add) {
            const newLocalSchedules = [
                ...newSchedules,
                ...localSchedules,
            ];
            const uniqueSchedules = newLocalSchedules.filter((schedule, index, self) => {
                const stringSchedule = JSON.stringify(schedule);
                return index === self.findIndex((s) => JSON.stringify(s) === stringSchedule);
            });
            localStorage.setItem('schedules', JSON.stringify(uniqueSchedules));
        } else localStorage.setItem('schedules', JSON.stringify(newSchedules));

        const localJSON = JSON.parse(localStorage.getItem('schedules') || '[]');
        const localSchedulesFromJSON: SchedulesType = localJSON;
        setLocalDefaultSchedules(localSchedulesFromJSON);
    };

    const setCloudSchedules = (newSchedules: SchedulesCloudType) => {
        newSchedules.reverse();
        const data: Array<any> = newSchedules;
        data.forEach((schedule, index) => {
            data[index].classes = JSON.parse(schedule.classes);
        });
        setCloudDefaultSchedules(data);
    };

    return (
        <SchedulesContext.Provider value={{
            localSchedules, setLocalSchedules,
            cloudSchedules, setCloudSchedules
        }}>
            {children}
        </SchedulesContext.Provider>
    );
}

'use client';

import { createContext, useState } from 'react';

import { errorToast } from '../../utils/toast';

import { ProviderJSXPropsType, SelectedClassesContextProviderPropsType, SelectedClassesContextType, SelectedClassesType } from './types';


let hasError = false;
const MAX_CLASSES = 4;
const MAX_DISCIPLINES = 11;

export const SelectedClassesContext = createContext({} as SelectedClassesContextType);

const handleError = (message: string) => {
    errorToast(message);
    hasError = true;
};

function handleMaxDisciplinesError(value: SelectedClassesType) {
    if (value.size > MAX_DISCIPLINES) {
        handleError(`Você só pode escolher até ${MAX_DISCIPLINES} disciplinas!`);
    }
}

function handleMaxClassesError(value: SelectedClassesType) {
    value.forEach(classes => {
        if (classes.size > MAX_CLASSES) {
            handleError(`Você só pode escolher até ${MAX_CLASSES} aulas da mesma disciplina!`);
        }
    });
}

function ProviderJSX({ children, ...props }: ProviderJSXPropsType) {
    return (
        <SelectedClassesContext.Provider value={props}>
            {children}
        </SelectedClassesContext.Provider>
    );
}

export default function SelectedClassesContextProvider({ children }: SelectedClassesContextProviderPropsType) {
    const [selectedClasses, setSelectedClassesDefault] = useState<SelectedClassesType>(new Map());
    const [classesChange, setClassesChange] = useState(false);
    const [currentYearPeriod, setCurrentYearPeriod] = useState('');

    function handleNoError(value: SelectedClassesType) {
        if (!value.size) setCurrentYearPeriod('');
        setSelectedClassesDefault(value);
        setClassesChange(!classesChange);
    }

    const setSelectedClasses = (value: SelectedClassesType) => {
        hasError = false;

        handleMaxClassesError(value);
        handleMaxDisciplinesError(value);
        if (!hasError) handleNoError(value);
    };

    return ProviderJSX({ children, selectedClasses, setSelectedClasses, classesChange, currentYearPeriod, setCurrentYearPeriod });
}

