    access?: string;
    first_name?: string;
    email?: string;
    picture_url?: string;
}

export const defaultUser: User = {
    is_anonymous: true,
};

export interface UserContextType {
    user: User;
    setUser: React.Dispatch<React.SetStateAction<User>>;
    isLoading: boolean;
    setLoading: React.Dispatch<React.SetStateAction<boolean>>;
}

